import { useCallback, useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import type { ConversationMeta, ProjectSummary } from '../types/conversation';
import {
  ApiError,
  getConversations,
  getRunningProjectScripts,
  listProjects,
  stopAllProjectScripts,
  type RunningProjectScript,
} from '../lib/api';
import { useServerEvents } from '../hooks/useServerEvents';
import { ProjectCard } from '../components/ProjectCard';
import { ConversationList } from '../components/ConversationList';
import { Button } from '../components/ui/Button';
import { Input } from '../components/ui/Input';
import { CreateConversationModal } from '../components/CreateConversationModal';
import { CreateProjectModal } from '../components/CreateProjectModal';

type State = 'loading' | 'ready' | 'error';

export function DashboardPage() {
  const navigate = useNavigate();
  const [projects, setProjects] = useState<ProjectSummary[]>([]);
  const [conversations, setConversations] = useState<ConversationMeta[]>([]);
  const [runningScripts, setRunningScripts] = useState<RunningProjectScript[]>([]);
  const [state, setState] = useState<State>('loading');
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);
  const [stoppingAll, setStoppingAll] = useState(false);
  const [projectSearch, setProjectSearch] = useState('');

  // New Conversation Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isProjectModalOpen, setIsProjectModalOpen] = useState(false);

  const fetchData = useCallback(async (refresh: boolean) => {
    if (refresh) setRefreshing(true);
    setError(null);
    try {
      const [projectList, convList] = await Promise.all([
        listProjects({ refresh }),
        getConversations(),
      ]);
      const running = await getRunningProjectScripts().catch(() => [] as RunningProjectScript[]);
      setProjects(projectList);
      setRunningScripts(running);
      setConversations(
        [...convList].sort((a, b) => Date.parse(b.updatedAt) - Date.parse(a.updatedAt)),
      );
      setState('ready');
    } catch (err: unknown) {
      setError(err instanceof ApiError ? err.message : 'Erreur inattendue.');
      setState('error');
    } finally {
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    void fetchData(false);
  }, [fetchData]);

  // Real-time: a new/updated conversation file bumps counts + the recent list.
  useServerEvents(
    useCallback((event) => {
      if (
        event.type !== 'conversations-changed' &&
        event.type !== 'projects-changed' &&
        event.type !== 'process-status'
      ) {
        return;
      }
      void fetchData(true);
    }, [fetchData]),
  );

  const filteredProjects = projects.filter((p) =>
    p.name.toLowerCase().includes(projectSearch.toLowerCase())
  );

  const totalConversations = conversations.length;
  const openCount = conversations.filter((c) => c.status !== 'completed' && c.status !== 'archived').length;

  const handleStopAllScripts = async () => {
    setStoppingAll(true);
    try {
      await stopAllProjectScripts();
      await fetchData(true);
    } finally {
      setStoppingAll(false);
    }
  };

  return (
    <div className="mx-auto max-w-6xl px-5 py-9 sm:px-8 sm:py-12">
      <header className="mb-10 flex flex-wrap items-end justify-between gap-5">
        <div>
          <p className="eyebrow text-copper">L’atelier</p>
          <h1 className="mt-1.5 font-display text-4xl leading-none text-ink sm:text-[2.75rem]">
            Tableau de bord
          </h1>
          <p className="mt-3 max-w-xl text-sm leading-relaxed text-ink-soft">
            Tous les projets de <code className="font-mono text-xs text-copper-deep">~/Desktop/my-projets</code> et
            les conversations en cours avec Claude, au même endroit.
          </p>
        </div>
        <div className="flex gap-3">
          <Button variant="secondary" onClick={() => void fetchData(true)} loading={refreshing}>
            <span aria-hidden>↻</span> Rafraîchir
          </Button>
          <Button variant="secondary" onClick={() => setIsProjectModalOpen(true)}>
            + Nouveau Projet
          </Button>
          <Button onClick={() => setIsModalOpen(true)}>
            + Nouvelle Conversation
          </Button>
        </div>
      </header>

      {state === 'error' && (
        <div className="mb-8 rounded-lg border border-copper/30 bg-copper/5 px-4 py-3 text-sm text-copper-deep">
          {error}
        </div>
      )}

      {state === 'loading' ? (
        <SkeletonGrid />
      ) : (
        <>
          <section className="mb-14">
            <SectionHeader index="01" title="Projets" meta={`${projects.length} dépôts`} />

            <div className="mb-6 max-w-sm">
              <Input
                type="text"
                placeholder="Rechercher un projet par nom..."
                value={projectSearch}
                onChange={(e) => setProjectSearch(e.target.value)}
              />
            </div>

            {filteredProjects.length === 0 ? (
              <Empty>{projectSearch ? "Aucun projet ne correspond à votre recherche." : "Aucun projet détecté."}</Empty>
            ) : (
              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
                {filteredProjects.map((project) => (
                  <ProjectCard key={project.slug} project={project} />
                ))}
              </div>
            )}
          </section>

          <section>
            <SectionHeader
              index="02"
              title="Scripts en cours"
              meta={`${runningScripts.length} tâche${runningScripts.length > 1 ? 's' : ''} active${runningScripts.length > 1 ? 's' : ''}`}
            />
            <RunningScriptsPanel
              scripts={runningScripts}
              onStopAll={handleStopAllScripts}
              stoppingAll={stoppingAll}
            />
          </section>

          <section className="mt-14">
            <SectionHeader
              index="03"
              title="Conversations récentes"
              meta={`${openCount} en cours · ${totalConversations} au total`}
            />
            <ConversationList conversations={conversations.slice(0, 10)} />
          </section>
        </>
      )}

      {/* NEW CONVERSATION MODAL DIALOG */}
      <CreateConversationModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        projects={projects}
        onCreated={(slug, id) => {
          navigate(`/c/${slug}/${id}`, { viewTransition: true });
        }}
      />

      {/* NEW PROJECT MODAL DIALOG */}
      <CreateProjectModal
        isOpen={isProjectModalOpen}
        onClose={() => setIsProjectModalOpen(false)}
      />
    </div>
  );
}

function RunningScriptsPanel({
  scripts,
  onStopAll,
  stoppingAll,
}: {
  scripts: RunningProjectScript[];
  onStopAll: () => void;
  stoppingAll: boolean;
}) {
  if (scripts.length === 0) {
    return (
      <p className="rounded-lg border border-dashed border-line bg-paper-card/60 px-4 py-8 text-center text-sm text-ink-faint">
        Aucun script ne roule actuellement.
      </p>
    );
  }

  return (
    <div className="space-y-3">
      <div className="flex justify-end">
        <Button
          variant="secondary"
          onClick={onStopAll}
          loading={stoppingAll}
          disabled={scripts.length === 0}
        >
          Arrêter tous les scripts
        </Button>
      </div>
      <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
        {scripts.map(({ project, script }) => (
          <Link
            key={`${project.slug}-${script.name}`}
            to={`/p/${project.slug}?tab=devops`}
            className="rounded-lg border border-line bg-paper-card px-4 py-3 shadow-warm-sm transition-colors hover:border-copper/45 hover:bg-paper-raised"
          >
            <div className="flex items-center gap-2">
              <span className="relative flex h-2.5 w-2.5">
                <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-status-done opacity-60" />
                <span className="relative inline-flex h-2.5 w-2.5 rounded-full bg-status-done" />
              </span>
              <span className="font-mono text-xs font-semibold text-ink">{script.name}</span>
              <span className="ml-auto font-mono text-[0.6875rem] uppercase tracking-wide text-ink-faint">
                En cours
              </span>
            </div>
            <p className="mt-2 font-display text-lg text-ink">{project.name}</p>
            <p className="mt-1 truncate font-mono text-[0.6875rem] text-ink-faint">{script.cmd}</p>
            <div className="mt-3 flex flex-wrap gap-3 font-mono text-[0.65rem] uppercase tracking-wide text-ink-faint">
              {script.lastRunAt && <span>Démarré {formatShortTime(script.lastRunAt)}</span>}
              {script.cpu !== undefined && <span>{script.cpu.toFixed(0)}% CPU</span>}
              {script.memory !== undefined && <span>{script.memory.toFixed(0)} Mo</span>}
            </div>
          </Link>
        ))}
      </div>
    </div>
  );
}

