function runCmd(cmd: string, args: string[], cwd: string, slug: string): Promise<number | null> {
  return new Promise((resolve, reject) => {
    const child = spawn(cmd, args, { cwd, env: { ...process.env, FORCE_COLOR: '1' }, shell: true });

    child.stdout?.on('data', (data) => {
      publish({
        type: 'project-scaffold-progress',
        slug,
        status: 'running',
        text: data.toString('utf8'),
      });
    });

    child.stderr?.on('data', (data) => {
      publish({
        type: 'project-scaffold-progress',
        slug,
        status: 'running',
        text: data.toString('utf8'),
      });
    });

    child.on('close', (code) => {
      if (code === 0) resolve(code);
      else reject(new Error(`Command "${cmd} ${args.join(' ')}" exited with code ${code}`));
    });

    child.on('error', (err) => {
      reject(err);
    });
  });
}

