/**
 * Spawns a script from the project's package.json.
 */
export async function startProcess(projectSlug: string, scriptName: string): Promise<void> {
  const key = getProcessKey(projectSlug, scriptName);
  const existing = processes.get(key);

  if (existing && existing.status === 'running') {
    throw new Error(`Process ${key} is already running.`);
  }

  const project = await getProject(projectSlug);
  if (!project) {
    throw new Error(`Project ${projectSlug} not found.`);
  }

  const pkgPath = path.join(project.path, 'package.json');
  let pkg: any;
  try {
    const raw = await fs.readFile(pkgPath, 'utf8');
    pkg = JSON.parse(raw);
  } catch (err) {
    throw new Error(`Failed to read package.json for project ${projectSlug}: ${String(err)}`);
  }

  if (!pkg.scripts || !pkg.scripts[scriptName]) {
    throw new Error(`Script "${scriptName}" not found in project ${projectSlug}.`);
  }

  const pkgManager = project.packageManager || 'npm';
  const logsBuffer: string[] = existing ? existing.logs : [];
  // Clear logs on fresh start
  logsBuffer.length = 0;

  console.log(`[workstation] Spawning script "${scriptName}" for project "${projectSlug}" using ${pkgManager}`);

  const logDir = path.join(ROOT, 'data', 'logs', projectSlug);
  await fs.mkdir(logDir, { recursive: true });
  const logPath = path.join(logDir, `${scriptName}.log`);

  // Write session separator to log file
  try {
    await fs.appendFile(
      logPath,
      `\n--- Démarrage de la tâche "${scriptName}" le ${new Date().toLocaleString('fr-FR')} ---\n`,
      'utf8'
    );
  } catch (err) {
    console.error(`Failed to write session header to ${logPath}:`, err);
  }

  const logStream = createWriteStream(logPath, { flags: 'a', encoding: 'utf8' });

  const child = spawn(pkgManager, ['run', scriptName], {
    cwd: project.path,
    env: { ...process.env, FORCE_COLOR: '1' },
    shell: true,
    detached: true, // Run in a new process group to allow killing the entire process tree
  });

  const procInfo: RunningProcess = {
    child,
    logs: logsBuffer,
    status: 'running',
    startedAt: new Date().toISOString(),
    logStream,
  };

  processes.set(key, procInfo);
  runHistory.set(key, { lastRunAt: procInfo.startedAt });

  // Publish process-status event
  publish({
    type: 'process-status',
    slug: projectSlug,
    script: scriptName,
    status: 'running',
    cpu: 0,
    memory: 0,
  });

  const handleData = (chunk: Buffer) => {
    const text = chunk.toString('utf8');
    const lines = text.split(/\r?\n/);
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      if (i === lines.length - 1 && line === '') {
        continue;
      }

      logsBuffer.push(line);
      if (logsBuffer.length > 300) {
        logsBuffer.shift();
      }

      // Write to persistent log file
      logStream.write(line + '\n');

      // Publish log event to the event bus
      publish({
        type: 'process-log',
        slug: projectSlug,
        script: scriptName,
        text: line,
      });
    }
  };

  child.stdout?.on('data', handleData);
  child.stderr?.on('data', handleData);

  child.on('close', (code) => {
    console.log(`[workstation] Process "${key}" exited with code ${code}`);
    procInfo.status = 'stopped';
    procInfo.finishedAt = new Date().toISOString();
    procInfo.exitCode = code;
    procInfo.cpu = undefined;
    procInfo.memory = undefined;
    runHistory.set(key, {
      lastRunAt: procInfo.startedAt,
      lastFinishedAt: procInfo.finishedAt,
      durationMs: Date.parse(procInfo.finishedAt) - Date.parse(procInfo.startedAt),
      exitCode: code,
    });
    void appendRunHistory(projectSlug, {
      script: scriptName,
      startedAt: procInfo.startedAt,
      finishedAt: procInfo.finishedAt,
      durationMs: Date.parse(procInfo.finishedAt) - Date.parse(procInfo.startedAt),
      exitCode: code,
    });
    logStream.end();
    publish({
      type: 'process-status',
      slug: projectSlug,
      script: scriptName,
      status: 'stopped',
      cpu: 0,
      memory: 0,
    });
  });

  child.on('error', (err) => {
    console.error(`[workstation] Process "${key}" error:`, err);
    logsBuffer.push(`System Error: ${err.message}`);
    if (logsBuffer.length > 300) {
      logsBuffer.shift();
    }
    logStream.write(`System Error: ${err.message}\n`);
    logStream.end();
    procInfo.status = 'stopped';
    procInfo.finishedAt = new Date().toISOString();
    procInfo.exitCode = null;
    procInfo.cpu = undefined;
    procInfo.memory = undefined;
    runHistory.set(key, {
      lastRunAt: procInfo.startedAt,
      lastFinishedAt: procInfo.finishedAt,
      durationMs: Date.parse(procInfo.finishedAt) - Date.parse(procInfo.startedAt),
      exitCode: null,
    });
    void appendRunHistory(projectSlug, {
      script: scriptName,
      startedAt: procInfo.startedAt,
      finishedAt: procInfo.finishedAt,
      durationMs: Date.parse(procInfo.finishedAt) - Date.parse(procInfo.startedAt),
      exitCode: null,
    });
    publish({
      type: 'process-status',
      slug: projectSlug,
      script: scriptName,
      status: 'stopped',
      cpu: 0,
      memory: 0,
    });
  });
}

export async function stopAllProcesses(projectSlug?: string): Promise<number> {
  const running = Array.from(processes.keys())
    .map((key) => {
      const [slug, script] = key.split(':');
      return { slug, script };
    })
    .filter(({ slug, script }) => {
      if (projectSlug && slug !== projectSlug) return false;
      return isProcessRunning(slug, script);
    });

  await Promise.all(running.map(({ slug, script }) => stopProcess(slug, script)));
  return running.length;
}

/**
 * Stops a running script.
 */
export async function stopProcess(projectSlug: string, scriptName: string): Promise<void> {
  const key = getProcessKey(projectSlug, scriptName);
  const proc = processes.get(key);

  if (!proc || proc.status !== 'running') {
    return;
  }

  console.log(`[workstation] Stopping process group for "${key}"`);

  // Kill the entire process group (shell wrapper + actual running commands)
  if (proc.child.pid) {
    try {
      process.kill(-proc.child.pid, 'SIGTERM');
    } catch (err) {
      console.warn(`[workstation] Failed to kill process group -${proc.child.pid}, falling back to child.kill:`, err);
      proc.child.kill('SIGTERM');
    }
  } else {
    proc.child.kill('SIGTERM');
  }

  // Best effort backup: if it doesn't close after 2 seconds, kill it forcefully
  const forceKillTimeout = setTimeout(() => {
    if (proc.status === 'running') {
      console.warn(`[workstation] Process "${key}" did not exit. Sending SIGKILL to group.`);
      if (proc.child.pid) {
        try {
          process.kill(-proc.child.pid, 'SIGKILL');
        } catch (err) {
          proc.child.kill('SIGKILL');
        }
      } else {
        proc.child.kill('SIGKILL');
      }
    }
  }, 2000);

  // Clear timeout if child exits naturally
  proc.child.on('close', () => {
    clearTimeout(forceKillTimeout);
  });
}

/**
 * Lists all npm/bun scripts for a project, indicating which are running.
 */
export async function getProjectScripts(
  projectSlug: string
): Promise<{
  name: string;
  cmd: string;
  status: 'idle' | 'running' | 'success' | 'failed' | 'stopped';
  logs: string;
  cpu?: number;
  memory?: number;
  lastRunAt?: string;
  lastFinishedAt?: string;
  durationMs?: number;
  exitCode?: number | null;
}[]> {
  const project = await getProject(projectSlug);
  if (!project) {
    throw new Error(`Project ${projectSlug} not found.`);
  }

  const pkgPath = path.join(project.path, 'package.json');
  try {
    const raw = await fs.readFile(pkgPath, 'utf8');
    const pkg = JSON.parse(raw);
    const scripts = pkg.scripts || {};

    const promises = Object.entries(scripts).map(async ([name, cmd]) => {
      const key = getProcessKey(projectSlug, name);
      const proc = processes.get(key);
      const history = runHistory.get(key);
      let logs = '';
      if (proc) {
        logs = proc.logs.join('\n');
      } else {
        const logPath = path.join(ROOT, 'data', 'logs', projectSlug, `${name}.log`);
        const lastLines = await readLastLines(logPath, 300);
        logs = lastLines.join('\n');
      }
      return {
        name,
        cmd: cmd as string,
        status: proc
          ? (proc.status === 'running' ? ('running' as const) : ('stopped' as const))
          : ('idle' as const),
        logs,
        cpu: proc?.cpu,
        memory: proc?.memory,
        lastRunAt: proc?.startedAt ?? history?.lastRunAt,
        lastFinishedAt: proc?.finishedAt ?? history?.lastFinishedAt,
        durationMs:
          proc?.finishedAt && proc.startedAt
            ? Date.parse(proc.finishedAt) - Date.parse(proc.startedAt)
            : history?.durationMs,
        exitCode: proc?.exitCode ?? history?.exitCode,
      };
    });
    return Promise.all(promises);
  } catch {
    return [];
  }
}

export async function getScriptLogText(projectSlug: string, scriptName: string): Promise<string> {
  const procLogs = getProcessLogs(projectSlug, scriptName);
  if (procLogs.length > 0) return procLogs.join('\n');
  const logPath = path.join(ROOT, 'data', 'logs', projectSlug, `${scriptName}.log`);
  try {
    return await fs.readFile(logPath, 'utf8');
  } catch {
    return '';
  }
}

