 */
async function readLastLines(filePath: string, maxLines: number = 300): Promise<string[]> {
  try {
    const content = await fs.readFile(filePath, 'utf8');
    const lines = content.split(/\r?\n/);
    if (lines.length > 0 && lines[lines.length - 1] === '') {
      lines.pop();
    }
    return lines.slice(-maxLines);
  } catch {
    return [];
  }
}

function historyPath(projectSlug: string): string {
  return path.join(ROOT, 'data', 'logs', projectSlug, 'runs.json');
}

async function appendRunHistory(projectSlug: string, entry: RunHistoryEntry): Promise<void> {
  const filePath = historyPath(projectSlug);
  try {
    await fs.mkdir(path.dirname(filePath), { recursive: true });
    let entries: RunHistoryEntry[] = [];
    try {
      const raw = await fs.readFile(filePath, 'utf8');
      const parsed = JSON.parse(raw);
      entries = Array.isArray(parsed) ? parsed : [];
    } catch {
      entries = [];
    }
    entries.unshift(entry);
    await fs.writeFile(filePath, JSON.stringify(entries.slice(0, 80), null, 2), 'utf8');
  } catch (err) {
    console.error(`Failed to persist run history for ${projectSlug}:`, err);
  }
}

export async function getRunHistory(projectSlug: string): Promise<RunHistoryEntry[]> {
  try {
    const raw = await fs.readFile(historyPath(projectSlug), 'utf8');
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

