import fs from 'node:fs/promises';
import path from 'node:path';

const SETTINGS_DIR = path.join(process.cwd(), 'data', 'project-settings');

export interface ScriptServerSettings {
  port?: number;
  host?: string;
  url?: string;
  env?: Record<string, string>;
}

export interface ProjectSettings {
  favoriteScripts?: string[];
  scriptServers?: Record<string, ScriptServerSettings>;
}

export async function readProjectSettings(slug: string): Promise<ProjectSettings> {
  try {
    const raw = await fs.readFile(path.join(SETTINGS_DIR, `${slug}.json`), 'utf8');
    const parsed = JSON.parse(raw);
    return typeof parsed === 'object' && parsed ? parsed : {};
  } catch {
    return {};
  }
}

export async function writeProjectSettings(slug: string, settings: ProjectSettings): Promise<void> {
  await fs.mkdir(SETTINGS_DIR, { recursive: true });
  await fs.writeFile(path.join(SETTINGS_DIR, `${slug}.json`), JSON.stringify(settings, null, 2), 'utf8');
}

export async function getScriptServerSettings(
  slug: string,
  scriptName: string,
): Promise<ScriptServerSettings | undefined> {
  const settings = await readProjectSettings(slug);
  return settings.scriptServers?.[scriptName];
}

