/**
 * Typed fetch wrapper over the Express API mounted at /api.
 * Every helper throws an `ApiError` on a non-2xx response so callers can
 * surface a friendly message.
 */

export class ApiError extends Error {
  readonly status: number;

  constructor(message: string, status: number) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
  }
}

const REQUEST_TIMEOUT_MS = 10_000;

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  let res: Response;
  try {
    res = await fetch(path, {
      headers: { Accept: 'application/json', ...(init?.headers ?? {}) },
      ...init,
      signal: controller.signal,
    });
  } catch (cause) {
    const aborted = cause instanceof DOMException && cause.name === 'AbortError';
    throw new ApiError(
      aborted
        ? 'Le serveur ne répond pas à temps. Essayez de recharger la page.'
        : 'Impossible de joindre le serveur. Vérifiez qu’il est démarré.',
      0,
    );
  } finally {
    window.clearTimeout(timeout);
  }

  if (!res.ok) {
    let detail = '';
    try {
      const body = (await res.json()) as { error?: string; message?: string };
      detail = body.error ?? body.message ?? '';
    } catch {
      detail = res.statusText;
    }
    throw new ApiError(
      detail || `La requête a échoué (HTTP ${res.status}).`,
      res.status,
    );
  }

  return (await res.json()) as T;

