async function statMtimeSafe(dir: string): Promise<string> {
  try {
    const stat = await fs.stat(dir);
    return stat.mtime.toISOString();
  } catch {
    // Broken symlink, removed between readdir and stat, EACCES, etc.
    return new Date(0).toISOString();
  }
}

async function scanOne(name: string): Promise<ProjectSummary> {
  const dir = path.join(PROJECTS_ROOT, name);
  const slug = slugify(name);

  // Every helper below already swallows its own errors, so a single bad
  // project yields a degraded-but-valid summary instead of taking the whole
  // scan down. statMtimeSafe is the last unguarded fs call and is wrapped too.
  const [
    pkg,
    isGit,
    packageManager,
    hasClaudeMd,
    hasReadme,
    lastModified,
    lastCommitDate,
    conversationCount,
  ] = await Promise.all([
    readJsonSafe(path.join(dir, 'package.json')),
    pathExists(path.join(dir, '.git')),
    detectPackageManager(dir),
    pathExists(path.join(dir, 'CLAUDE.md')),
    (async () =>
      (await pathExists(path.join(dir, 'README.md'))) ||
      (await pathExists(path.join(dir, 'readme.md'))))(),
    statMtimeSafe(dir),
    getLastCommitDate(dir),
    countConversations(slug),
  ]);

  const { type, framework } = classify(pkg);

  return {
    slug,
    name,
    path: dir,
    isGit,
    type,
    framework,
    packageManager,
    lastCommitDate,
    lastModified,
    hasClaudeMd,
    hasReadme,
    conversationCount,
  };
}

