+  const value = `${scriptName} ${command}`.toLowerCase();
+  return /\b(dev|serve|server|start|preview)\b/.test(value) ||
+    /\b(vite|next dev|next start|astro dev|nuxt dev|serve)\b/.test(value);
+}
