import { readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

const settingsDir = '/Users/elmabi/Desktop/my-projets/workstation/data/project-settings';
const projectsRoot = '/Users/elmabi/Desktop/my-projets';
const used = new Set();
const files = (await readdir(settingsDir)).filter((file) => file.endsWith('.json'));
const settingsBySlug = new Map();

for (const file of files) {
  const slug = path.basename(file, '.json');
  const settings = JSON.parse(await readFile(path.join(settingsDir, file), 'utf8'));
  settingsBySlug.set(slug, settings);
  for (const server of Object.values(settings.scriptServers ?? {})) {
    if (server?.port) used.add(server.port);
  }
}

function slugify(value) {
  return value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'project';
}

function isServerScript(name, command) {
  const value = `${name} ${command}`.toLowerCase();
  return /\b(dev|serve|server|start|preview)\b/.test(value) || /\b(vite|next dev|next start|astro dev|nuxt dev|serve)\b/.test(value);
}

function commandOverride(command, port, host) {
  const trimmed = command.trim();
  if (/^(npx\s+)?serve(\s|$)/.test(trimmed) && !/\s(-l|--listen|--port|-p)\b/.test(trimmed)) {
    return `${trimmed} -l tcp://${host}:${port}`;
  }
}

const projectDirs = await readdir(projectsRoot, { withFileTypes: true });
const slugToPath = new Map(projectDirs.filter((d) => d.isDirectory()).map((d) => [slugify(d.name), path.join(projectsRoot, d.name)]));

for (const [slug, settings] of settingsBySlug) {
  const favorites = settings.favoriteScripts ?? [];
  if (favorites.length === 0) continue;
  const projectPath = slugToPath.get(slug);
  if (!projectPath) continue;
  let pkg;
  try {
    pkg = JSON.parse(await readFile(path.join(projectPath, 'package.json'), 'utf8'));
  } catch {
    continue;
  }
  let changed = false;
  const scriptServers = { ...(settings.scriptServers ?? {}) };
  for (const script of favorites) {
    if (scriptServers[script]) continue;
    const command = pkg.scripts?.[script];
    if (typeof command !== 'string' || !isServerScript(script, command)) continue;
    let port = 3000;
    while (used.has(port) && port <= 3099) port++;
    if (port > 3099) throw new Error('Aucun port disponible entre 3000 et 3099.');
    used.add(port);
    const host = '127.0.0.1';
    const override = commandOverride(command, port, host);
    scriptServers[script] = { port, host, url: `http://${host}:${port}`, ...(override ? { command: override } : {}) };
    changed = true;
  }
  if (changed) {
    await writeFile(path.join(settingsDir, `${slug}.json`), `${JSON.stringify({ ...settings, scriptServers }, null, 2)}\n`, 'utf8');
    console.log(`updated ${slug}`);
  }
}
