import fs from 'node:fs/promises';
import path from 'node:path';
import { scanProjects } from './projectScanner';

const SETTINGS_DIR = path.join(process.cwd(), 'data', 'project-settings');
const DEFAULT_HOST = '127.0.0.1';
const AUTO_PORT_START = 3000;
const AUTO_PORT_END = 3099;

export interface ScriptServerSettings {
  port?: number;
  host?: string;
  url?: string;
  env?: Record<string, string>;
  command?: string;
}

export interface ProjectSettings {
  favoriteScripts?: string[];
  scriptServers?: Record<string, ScriptServerSettings>;
}

export async function readProjectSettings(slug: string): Promise<ProjectSettings> {
  try {
    const raw = await fs.readFile(path.join(SETTINGS_DIR, `${slug}.json`), 'utf8');
    const parsed = JSON.parse(raw);
    return typeof parsed === 'object' && parsed ? parsed : {};
  } catch {
    return {};
  }
}

export async function writeProjectSettings(slug: string, settings: ProjectSettings): Promise<void> {
  await fs.mkdir(SETTINGS_DIR, { recursive: true });
  await fs.writeFile(path.join(SETTINGS_DIR, `${slug}.json`), JSON.stringify(settings, null, 2), 'utf8');
}

export async function getScriptServerSettings(
  slug: string,
  scriptName: string,
): Promise<ScriptServerSettings | undefined> {
  const settings = await readProjectSettings(slug);
  return settings.scriptServers?.[scriptName];
}

function isServerScript(scriptName: string, command: string): boolean {
  const value = `${scriptName} ${command}`.toLowerCase();
  return /\b(dev|serve|server|start|preview)\b/.test(value) ||
    /\b(vite|next dev|next start|astro dev|nuxt dev|serve)\b/.test(value);
}

function buildCommandOverride(command: string, port: number, host: string): string | undefined {
  const trimmed = command.trim();
  if (trimmed === 'serve') {
    return `bunx serve -l tcp://${host}:${port}`;
  }
  if (/^(npx\s+)?serve(\s|$)/.test(trimmed) && !/\s(-l|--listen|--port|-p)\b/.test(trimmed)) {
    return `${trimmed} -l tcp://${host}:${port}`;
  }
  return undefined;
}

async function readUsedPorts(): Promise<Set<number>> {
  const used = new Set<number>();
  let files: string[] = [];
  try {
    files = await fs.readdir(SETTINGS_DIR);
  } catch {
    return used;
  }

  await Promise.all(files.filter((file) => file.endsWith('.json')).map(async (file) => {
    const settings = await readProjectSettings(path.basename(file, '.json'));
    for (const server of Object.values(settings.scriptServers ?? {})) {
      if (server.port) used.add(server.port);
    }
  }));
  return used;
}

async function nextAvailableConfiguredPort(): Promise<number> {
  const used = await readUsedPorts();
  for (let port = AUTO_PORT_START; port <= AUTO_PORT_END; port++) {
    if (!used.has(port)) return port;
  }
  throw new Error(`Aucun port disponible entre ${AUTO_PORT_START} et ${AUTO_PORT_END}.`);
}

export async function inferScriptServerSettings(
  slug: string,
  scriptName: string,
): Promise<ScriptServerSettings | undefined> {
  const project = (await scanProjects()).find((candidate) => candidate.slug === slug);
  if (!project) return undefined;

  try {
    const raw = await fs.readFile(path.join(project.path, 'package.json'), 'utf8');
    const pkg = JSON.parse(raw);
    const command = pkg.scripts?.[scriptName];
    if (typeof command !== 'string' || !isServerScript(scriptName, command)) return undefined;

    const port = await nextAvailableConfiguredPort();
    const host = DEFAULT_HOST;
    const commandOverride = buildCommandOverride(command, port, host);
    return {
      port,
      host,
      url: `http://${host}:${port}`,
      ...(commandOverride ? { command: commandOverride } : {}),
    };
  } catch {
    return undefined;
  }
}

